export function initNotifications(c){const {$,state,req,element,button,toast}=c;const rpc=(action,payload={})=>req('/rest/v1/rpc/push_action',{method:'POST',body:{action,payload}});let publicKey;const ready=()=>Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error('تعذّر تجهيز الإشعارات. حدّث التطبيق وحاول مجددًا.')),6000))]);const section=element('section');section.id='notification-settings';section.innerHTML='<h3>إشعارات الجوال</h3><p class="muted">تنبيهات عامة دون عرض أسماء أو نص الرسائل على شاشة القفل. على الآيفون: افتح النسخة المضافة إلى الشاشة الرئيسية. قد يتأخر وصول التنبيه بحسب الجهاز وحجم الإرسال.</p><label class="inline"><input id="notify-news" type="checkbox" checked> الأخبار الجديدة</label><label class="inline"><input id="notify-private" type="checkbox" checked> الرسائل الخاصة الواردة</label><p id="notify-status" role="status"></p>';$('profile-dialog').append(section);const enable=button('🔔 تفعيل الإشعارات على هذا الجهاز',activate,'secondary'),disable=button('إيقاف إشعارات هذا الجهاز',deactivate,'text-button');enable.id='notifications-enable';disable.id='notifications-disable';section.append(enable,disable);
 function supported(){return 'Notification'in globalThis&&'serviceWorker'in navigator&&'PushManager'in globalThis;}
 function bytes(s){const raw=atob(s.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0));}
 async function load(){enable.hidden=disable.hidden=state.profile?.status!=='active';if(!supported()){$('notify-status').textContent='الإشعارات غير مدعومة هنا. استخدم متصفحًا داعمًا؛ وعلى الآيفون افتح التطبيق من الشاشة الرئيسية.';return;}const k=await rpc('key');publicKey=k.publicKey;$('notify-status').textContent=Notification.permission==='granted'?'يمكن تفعيل الإشعارات أو حفظ اختياراتك لهذا الجهاز.':Notification.permission==='denied'?'الإذن مرفوض. غيّر إذن الإشعارات من إعدادات الجهاز إذا رغبت.':'اضغط تفعيل الإشعارات للموافقة من الجهاز.';}
 async function activate(){if(!supported())throw new Error('افتح التطبيق من الشاشة الرئيسية على الآيفون، أو من متصفح يدعم الإشعارات.');if(state.profile?.status!=='active')throw new Error('الإشعارات للأعضاء المعتمدين.');const permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('لم تمنح الجهاز إذن الإشعارات.');if(!publicKey)publicKey=(await rpc('key')).publicKey;const registration=await ready();let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes(publicKey)});await rpc('subscribe',{subscription:subscription.toJSON(),news:$('notify-news').checked,private_chat:$('notify-private').checked});$('notify-status').textContent='الإشعارات مفعّلة على هذا الجهاز.';toast('تم تفعيل الإشعارات وحفظ اختياراتك.');}
 async function deactivate(){if(!supported())return;const registration=await ready(),subscription=await registration.pushManager.getSubscription();if(subscription){try{if(state.user)await rpc('unsubscribe',{endpoint:subscription.endpoint});}finally{await subscription.unsubscribe();}}$('notify-status').textContent='إشعارات هذا الجهاز موقوفة.';}
 return {load,beforeLogout:deactivate};
}
